// Body: { "ticket": "...", "expected_team": "infra|billing|sales" (optional, scores the CLASSIFY answer) }
const body = $input.first().json.body || {};
const ticket = String(body.ticket || 'I was charged twice for my subscription this month').slice(0, 2000);
const expected_team = ['infra', 'billing', 'sales'].includes(body.expected_team) ? body.expected_team : null;
return [{ json: { ticket, expected_team, started_at: Date.now(), laya_calls: 0, laya_ms: 0 } }];

