// CLASSIFY: a System 1 CHOICE call picked the team.
const s = $('Prepare Ticket').first().json;
const item = $input.first().json;
const a = item.answers || {};
const team = a.team?.choice, conf = a.team?.confidence;
const ok = ['infra', 'billing', 'sales'].includes(team) && (v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)(conf);
const ms = Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : 0;
return [{ json: { ...s, laya_calls: s.laya_calls + 1, laya_ms: s.laya_ms + ms,
  classify: { call: 'choice', team: ok ? team : null, confidence: ok ? conf : 0, usable: ok, laya_ms: ms,
    team_correct: (s.expected_team && ok) ? team === s.expected_team : null } } }];

