// ROUTE: a System 1 NOUL call scored urgency. Plain code then applies the rule: the punchline.
const URGENT_MIN = 0.7;
const s = $('Read Classify').first().json;
const item = $input.first().json;
const u = item.answers?.urgent?.noul;
const ok = (v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)(u);
const ms = Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : 0;
const team = s.classify.team;
const route_if_handed_to_team = !ok || !team ? null : (u >= URGENT_MIN ? 'page_oncall:' + team : 'queue:' + team);
return [{ json: { ...s, laya_calls: s.laya_calls + 1, laya_ms: s.laya_ms + ms,
  route: { call: 'noul', urgent: ok ? u : null, usable: ok, laya_ms: ms,
    rule: 'urgent >= 0.7 pages on-call, else team queue (code, not the model)', route_if_handed_to_team } } }];

