// RANK: a System 1 NOUL call scored business impact. Code turns the score into a queue position.
const s = $('Route (code applies policy)').first().json;
const item = $input.first().json;
const im = item.answers?.impact?.noul;
const ok = (v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)(im);
const ms = Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : 0;
const priority = !ok ? 'unscored' : im >= 0.8 ? 'P1' : im >= 0.5 ? 'P2' : 'P3';
return [{ json: { ...s, laya_calls: s.laya_calls + 1, laya_ms: s.laya_ms + ms,
  rank: { call: 'noul', impact: ok ? im : null, priority, usable: ok, laya_ms: ms } } }];

