// GATE: a System 1 CHOICE call decided automate vs human. Invalid answer fails safe to human.
const s = $('Rank (priority from score)').first().json;
const item = $input.first().json;
const g = item.answers?.gate;
const ok = ['automate', 'human'].includes(g?.choice) && (v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)(g?.confidence);
const ms = Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : 0;
const decision = ok ? g.choice : 'human';
return [{ json: { ...s, laya_calls: s.laya_calls + 1, laya_ms: s.laya_ms + ms,
  gate: { call: 'choice', decision, confidence: ok ? g.confidence : 0, usable: ok, laya_ms: ms,
    note: ok ? null : 'Gate answer unusable, failed safe to human' } } }];

