// CHOOSE: a System 1 CHOICE call picked the action. Policy in code: urgent tickets are never auto-answered,
// and a low-confidence CLASSIFY (< 0.6) or unusable answer always escalates to System 2.
const s = $('Gate Decision').first().json;
const item = $input.first().json;
const c = item.answers?.action;
const ok = ['resolve_with_help_article', 'hand_to_team', 'escalate_to_system_2'].includes(c?.choice) && (v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)(c?.confidence);
const ms = Number.isFinite(item.total_duration) ? Math.round(item.total_duration / 1e6) : 0;
let action = ok ? c.choice : 'escalate_to_system_2';
const reasons = [];
if (!ok) reasons.push('choose answer unusable');
if (s.classify.confidence < 0.6) { action = 'escalate_to_system_2'; reasons.push('classify confidence < 0.6'); }
if (action === 'resolve_with_help_article' && (s.route.urgent === null || s.route.urgent >= 0.7)) { action = 'hand_to_team'; reasons.push('urgent tickets are not auto-answered'); }
let final_route = null;
if (action === 'hand_to_team') final_route = s.route.route_if_handed_to_team || 'human_review';
if (action === 'resolve_with_help_article') final_route = 'auto_reply:help_article';
return [{ json: { ...s, laya_calls: s.laya_calls + 1, laya_ms: s.laya_ms + ms,
  choose: { call: 'choice', model_pick: ok ? c.choice : null, confidence: ok ? c.confidence : 0, action, policy_overrides: reasons, usable: ok, laya_ms: ms },
  final_route } }];

// Every stage was a System 1 call; code only applied the policy.
const s = $('Choose Decision').first().json;
return [{ json: {
  ticket: s.ticket, final_route: s.final_route, decided_by: 'System 1 (Laya), policy in code',
  stages: { classify: s.classify, route: s.route, rank: s.rank, gate: s.gate, choose: s.choose },
  laya_calls: s.laya_calls, laya_total_ms: s.laya_ms, total_ms: Date.now() - s.started_at,
  note: 'Demo labels only: no page, queue or reply is executed.'
} }];

// The System 1 gate said a person should handle this. CHOOSE never ran.
const s = $('Gate Decision').first().json;
return [{ json: {
  ticket: s.ticket, final_route: 'human_review', decided_by: 'System 1 gate -> human',
  stages: { classify: s.classify, route: s.route, rank: s.rank, gate: s.gate, choose: { skipped: true } },
  laya_calls: s.laya_calls, laya_total_ms: s.laya_ms, total_ms: Date.now() - s.started_at,
  note: 'Demo labels only: no page, queue or reply is executed.'
} }];

// System 2 second opinion after System 1 chose to escalate (or classify was under 0.6). Still gated at 0.6.
const s = $('Choose Decision').first().json;
const item = $input.first().json;
let s2 = null;
try {
  const raw = String(item.response ?? '').replace(/```(?:json)?/gi, '').trim();
  s2 = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  if (!['infra', 'billing', 'sales'].includes(s2.team)
    || ![s2.urgent, s2.confidence].every(v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)) s2 = null;
} catch (_) { s2 = null; }
let final_route = 'human_review', decided_by = 'human (System 2 unsure or unavailable)';
if (s2 && s2.confidence >= 0.6) {
  final_route = (s2.urgent >= 0.7 ? 'page_oncall:' : 'queue:') + s2.team;
  decided_by = 'System 2 (Ollama), after System 1 escalated';
}
return [{ json: {
  ticket: s.ticket, final_route, decided_by,
  stages: { classify: s.classify, route: s.route, rank: s.rank, gate: s.gate, choose: {
    ...s.choose,
    system_2: s2 ? { urgent: s2.urgent, team: s2.team, confidence: s2.confidence, team_correct: s.expected_team ? s2.team === s.expected_team : null } : null,
    system_2_usable: !!s2,
    system_2_latency_ms: Math.round((item.total_duration || 0) / 1e6)
  } },
  laya_calls: s.laya_calls, laya_total_ms: s.laya_ms, total_ms: Date.now() - s.started_at,
  note: 'Demo labels only: no page, queue or reply is executed.'
} }];
